async (page) => {
  /* Shoot + audit console v2 pages at the listed sizes, both themes. Generated by mk.sh from shoot.tpl.js. */
  const D = '/home/vardan/projects/ETCAB/.claude/worktrees/console-linear-pass/docs/superpowers/design/2026-10-11-console-v2/'
  const WANT = 'partners?tab=wallet'.split(' '), SIZES = [[1440,900],[1366,768]]
  const out = {}
  for (const [w, h] of SIZES) {
    const ctx = await page.context().browser().newContext({ viewport: { width: w, height: h } })
    for (const f of WANT) for (const theme of ['light', 'dark']) {
      const p = await ctx.newPage(); const errs = []
      p.on('pageerror', (e) => errs.push(e.message))
      p.on('console', (m) => { if (m.type() === 'error') errs.push(m.text().slice(0, 140)) })
      const [fn, qs] = f.split('?')
      await p.goto(`http://localhost:8090/2026-10-11-console-v2/${fn}.html?theme=${theme}${qs ? '&' + qs : ''}`, { waitUntil: 'load' })
      const hasMap = await p.evaluate(() => !!document.getElementById('map'))
      if (hasMap) await p.waitForFunction(() => document.documentElement.dataset.mapReady, null, { timeout: 30000 }).catch(() => errs.push('mapReady timeout'))
      await p.evaluate(() => document.fonts.ready); await p.waitForTimeout(800)
      await p.evaluate(() => document.querySelector('.mockbar')?.remove())
      await p.screenshot({ path: `${D}shots/${fn}${qs ? '-' + qs.replace(/[^a-z0-9]/g, '') : ''}-${theme}${w === 1440 ? '' : '-' + w}.png` })
      const a = await p.evaluate(() => window.audit())
      const rows = await p.evaluate(() => { const q = document.getElementById('queue'); if (!q) return null; const Q = q.getBoundingClientRect(); return [...q.querySelectorAll('.r')].filter((r) => { const b = r.getBoundingClientRect(); return b.top >= Q.top - 1 && b.bottom <= Q.bottom + 1 }).length })
      out[`${f}-${theme}-${w}`] = { map: await p.evaluate(() => document.documentElement.dataset.mapReady || '-'), errs, overlaps: a.overlaps, clips: a.clips, contrast: a.contrast, small7: a.small7, truncated: a.truncated.length, worst: a.worstMargin, texts: a.checked.texts, queueRows: rows }
      await p.close()
    }
    await ctx.close()
  }
  return JSON.stringify(out)
}
